<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

use Override;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\Rbac\AllowListener;
use Civi\Lughauth\Shared\Security\Rbac\FieldsListener;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Psr\Container\ContainerInterface;

/**
 * Registers RBAC listeners and startup refresh for security policies.
 */
class SecurityPlugin extends MicroPlugin
{
    /**
     * Startup order for the RBAC cache refresh.
     */
    public const int STARTUP_ORDER = 1000;

    /**
     * Binds the reversible secret storage port to the local key ring implementation, and the
     * secret digester to its configured peppers.
     */
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ReversibleSecretStorage::class] = \DI\factory([KeyRingSecretStorage::class, 'fromConfig']);
        $def[SecretDigester::class] = \DI\factory([SecretDigester::class, 'fromConfig']);
        return $def;
    }
    /**
     * Registers RBAC listeners for allow and field access events.
     */
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(AllowDecision::class, AllowListener::class);
        $listener->registerListener(FieldsAccess::class, FieldsListener::class);
    }

    /**
     * Registers the RBAC cache refresh at startup.
     */
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->flush();
        }, SecurityPlugin::STARTUP_ORDER);
    }

}
